rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_DIMENSION_DEFINITION_NAME_UNIQUENESS_FORWARD_ONLY: Recovery requires a new forward changeset';
