changeSet.sql:
ALTER TABLE modeling_dimension_definition_migration_batch
    ADD CONSTRAINT ck_dimension_definition_migration_batch_checksum
    CHECK (migration_checksum ~ '^[0-9a-f]{64}$');
ALTER TABLE modeling_dimension_definition_migration_batch
    ADD CONSTRAINT ck_dimension_definition_migration_batch_status
    CHECK (status IN ('DRY_RUN', 'EXECUTED', 'ROLLED_BACK'));
ALTER TABLE modeling_dimension_definition_migration_batch
    ADD CONSTRAINT ck_dimension_definition_migration_batch_evidence
    CHECK (
        jsonb_typeof(dry_run_json) = 'object'
        AND (
            (status = 'DRY_RUN' AND execution_json IS NULL AND rollback_json IS NULL)
            OR (
                status = 'EXECUTED'
                AND jsonb_typeof(execution_json) = 'object'
                AND rollback_json IS NULL
            )
            OR (
                status = 'ROLLED_BACK'
                AND jsonb_typeof(execution_json) = 'object'
                AND jsonb_typeof(rollback_json) = 'object'
            )
        )
    );
ALTER TABLE modeling_dimension_definition_legacy_map
    ADD CONSTRAINT ck_dimension_definition_legacy_checksum
    CHECK (
        (migration_checksum IS NULL OR migration_checksum ~ '^[0-9a-f]{64}$')
        AND (NOT definition_created_by_batch OR migration_checksum IS NOT NULL)
    );
ALTER TABLE modeling_dimension_definition_revision
    ALTER CONSTRAINT fk_dimension_definition_revision_head
    DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE modeling_dimension_definition
    ALTER CONSTRAINT fk_dimension_definition_current_revision
    DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX idx_dimension_definition_migration_batch_status
    ON modeling_dimension_definition_migration_batch (tenant_id, status, last_modified_date DESC);

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_DIMENSION_DEFINITION_MIGRATION_BATCH_FORWARD_ONLY: Recovery requires a new forward changeset';
END $$;
